const h = P.h, k = P.k, a = P.a;
// Parametric: x = h + s, y = k + a*s^2.  Eliminate s = x - h  =>  y = k + a(x-h)^2
const X = (s) => h + s;
const Y = (s) => k + a * s * s;
const pts = [];
for (let i = 0; i <= 200; i++) { const s = -4 + 8 * i / 200; pts.push([X(s), Y(s)]); }
v.path(pts, { color: H.colors.accent, width: 2.5 });
// the SAME curve as a Cartesian function (drawn faintly on top to show they match)
v.fn(x => k + a * (x - h) * (x - h), { color: H.colors.good, width: 1.5 });
